def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width/full-height uniform lines are the compartment dividers.
    divider_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    divider_cols = {
        c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
    }

    def spans(n, dividers):
        out, start = [], 0
        for i in range(n):
            if i in dividers:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    row_spans = spans(h, divider_rows)
    col_spans = spans(w, divider_cols)

    # Find the background color among non-divider cells.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_spans
        for c0, c1 in col_spans
        for r in range(r0, r1)
        for c in range(c0, c1)
    )
    background = counts.most_common(1)[0][0]

    # Use the compartment containing the most non-background pattern cells.
    best = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            score = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if best is None or score > best[0]:
                best = (score, r0, r1, c0, c1)

    _, r0, r1, c0, c1 = best
    tile = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for a, b in row_spans:
        for x, y in col_spans:
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = tile[(r - a) % len(tile)][(c - x) % len(tile[0])]
    return out
